with transactions_by_account as (select account_id, sum(case when merchant = '7-Eleven' then 1 else 0 end) 7_eleven_count, round((100 * sum(case when merchant = '7-Eleven' then 1 else 0 end)) / count(*), 1) pct_7_eleven from transactions group by account_id) select a.account_type, a.customer_id, tba.7_eleven_count, tba.pct_7_eleven from accounts a join transactions_by_account tba on a.id = tba.account_id order by a.account_type, pct_7_eleven
